#include <Servo.h>
Servo servo;
const int POT = A0, TUGMA = 2;

void setup() {
  servo.attach(9);           // signal simi D9 ga
  pinMode(TUGMA, INPUT_PULLUP);
  Serial.begin(9600);
  servo.write(0);            // boshlangʻich holat: yopiq
