  // 2) tugma bosilmasa — potensiometr burchakni boshqaradi
  int burchak = map(analogRead(POT), 0, 1023, 0, 180);
  servo.write(burchak);
  Serial.print("burchak: "); Serial.println(burchak);
  delay(50);
}

